import{_ as a,o as i,c as t,a0 as e}from"./chunks/framework.DoRPXVp_.js";const g=JSON.parse('{"title":"Agent Sandbox (Pro)","description":"","frontmatter":{"title":"Agent Sandbox (Pro)"},"headers":[],"relativePath":"agent/sandbox-pro.md","filePath":"agent/sandbox-pro.md"}'),n={name:"agent/sandbox-pro.md"};function l(d,s,o,r,p,h){return i(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="agent-sandbox-—-pro-edition" tabindex="-1">Agent Sandbox — Pro Edition <a class="header-anchor" href="#agent-sandbox-—-pro-edition" aria-label="Permalink to &quot;Agent Sandbox — Pro Edition&quot;">​</a></h1><p>The Pro sandbox extends the <a href="/agent/sandbox">Community sandbox</a> with egress filtering, inbound port forwarding, a SOCKS5 proxy, and server-side NATS flow auditing.</p><h2 id="sandbox-run-—-one-command-sandbox" tabindex="-1"><code>sandbox run</code> — One-Command Sandbox <a class="header-anchor" href="#sandbox-run-—-one-command-sandbox" aria-label="Permalink to &quot;\`sandbox run\` — One-Command Sandbox&quot;">​</a></h2><p><code>lattice sandbox run</code> combines <code>start</code> + agent execution + cleanup into a single command. It supports two isolation modes:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># pod mode (default) — SOCKS5 proxy + ALL_PROXY injection</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lattice</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sandbox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --server-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://latticed:8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --token</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lt-xxx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agent.py</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># gvisor mode — runsc container isolation</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lattice</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sandbox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --server-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://latticed:8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --token</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lt-xxx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gvisor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent-rootfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/lib/lattice/rootfs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agent.py</span></span></code></pre></div><p><strong>pod mode</strong> starts a network sandbox, injects <code>ALL_PROXY</code> into the child process, and executes the given command. When the child exits, the sandbox is automatically cleaned up.</p><p><strong>gvisor mode</strong> runs the agent binary directly inside a gVisor runsc container. The first arg after <code>--</code> becomes the agent binary (unless <code>--agent-binary</code> is explicitly set).</p><table tabindex="0"><thead><tr><th>Flag</th><th>Mode</th><th>Description</th></tr></thead><tbody><tr><td><code>--mode</code></td><td>both</td><td>Isolation mode: <code>pod</code> (default) or <code>gvisor</code></td></tr><tr><td><code>--agent-rootfs</code></td><td>gvisor</td><td>Root filesystem path for runsc container</td></tr><tr><td><code>--agent-binary</code></td><td>gvisor</td><td>Agent entrypoint binary (defaults to first arg after <code>--</code>)</td></tr><tr><td><code>--agent-args</code></td><td>gvisor</td><td>Arguments passed to the agent binary</td></tr><tr><td><code>--proxy-addr</code></td><td>pod</td><td>SOCKS5 proxy listen address (empty = random port)</td></tr><tr><td><code>--ready-timeout</code></td><td>pod</td><td>Max wait for sandbox ready (default 30s)</td></tr><tr><td><code>--wg-port</code></td><td>pod</td><td>WireGuard UDP port (0 = random)</td></tr></tbody></table><h2 id="additional-flags-sandbox-start" tabindex="-1">Additional Flags (<code>sandbox start</code>) <a class="header-anchor" href="#additional-flags-sandbox-start" aria-label="Permalink to &quot;Additional Flags (\`sandbox start\`)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lattice sandbox start [flags]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Pro-only flags (pod mode):</span></span>
<span class="line"><span>  --egress-allow   strings   CIDR ranges to allow outbound (default: deny-all)</span></span>
<span class="line"><span>  --forward        strings   Overlay port → host address mappings (e.g. 8080:127.0.0.1:8080)</span></span>
<span class="line"><span>  --proxy-addr     string    Local address for SOCKS5 proxy (e.g. 127.0.0.1:1080)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Pro-only flags (gvisor mode):</span></span>
<span class="line"><span>  --mode gvisor              Enable gVisor runsc isolation</span></span>
<span class="line"><span>  --agent-rootfs  string     Path to container root filesystem (required for gvisor mode)</span></span>
<span class="line"><span>  --agent-binary  string     AI agent entrypoint binary inside container (required)</span></span>
<span class="line"><span>  --agent-args    strings    Arguments passed to the AI agent binary</span></span></code></pre></div><h2 id="egressfilter" tabindex="-1">EgressFilter <a class="header-anchor" href="#egressfilter" aria-label="Permalink to &quot;EgressFilter&quot;">​</a></h2><p>EgressFilter implements <code>PolicyChecker</code> — it intercepts every outbound connection attempt from the gVisor netstack and evaluates it against a CIDR allowlist. In <strong>pod mode</strong>, filtering happens inside gVisor&#39;s user-space netstack. In <strong>gVisor mode</strong>, egress filtering is enforced by pod iptables/eBPF on the real wg0 interface.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Only allow outbound to the tool service at 10.42.0.10 and HTTPS</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lattice</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sandbox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agent-001</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --server-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://lattice.internal:8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --token</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lt-xxx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --egress-allow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 10.42.0.10/32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --egress-allow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 0.0.0.0/0:443</span></span></code></pre></div><p>If no <code>--egress-allow</code> flags are provided, all egress is denied. Denied connections are logged to the audit file.</p><h2 id="forwardlistener-pod-mode-only" tabindex="-1">ForwardListener (pod mode only) <a class="header-anchor" href="#forwardlistener-pod-mode-only" aria-label="Permalink to &quot;ForwardListener (pod mode only)&quot;">​</a></h2><p>Forward inbound connections from the overlay network to a host-local address. Not applicable in gVisor mode.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Accept connections on overlay port 8080, forward to localhost:8080</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lattice</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sandbox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api-agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --server-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://lattice.internal:8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --token</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lt-xxx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --forward</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8080:127.0.0.1:8080</span></span></code></pre></div><p>Multiple <code>--forward</code> flags are supported.</p><h2 id="socks5-proxy-pod-mode-only" tabindex="-1">SOCKS5 Proxy (pod mode only) <a class="header-anchor" href="#socks5-proxy-pod-mode-only" aria-label="Permalink to &quot;SOCKS5 Proxy (pod mode only)&quot;">​</a></h2><p>Start a SOCKS5 proxy inside the gVisor sandbox (pod mode). All TCP connections through this proxy are routed through the WireGuard overlay with full policy enforcement and audit logging. Not applicable in gVisor mode — the AI agent connects to overlay IPs directly.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lattice</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sandbox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> browser-agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --server-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://lattice.internal:8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --token</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lt-xxx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --proxy-addr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:1080</span></span></code></pre></div><p>In your agent process:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ALL_PROXY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">socks5://127.0.0.1:1080</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://internal-api.example.com/data</span></span></code></pre></div><h2 id="nats-flow-audit-server-side" tabindex="-1">NATS Flow Audit (Server-side) <a class="header-anchor" href="#nats-flow-audit-server-side" aria-label="Permalink to &quot;NATS Flow Audit (Server-side)&quot;">​</a></h2><p>Pro adds server-side persistence of network flow events. The sandbox publishes to <code>lattice.audit.flow</code> on NATS; the control plane&#39;s <code>AuditConsumer</code> persists events to the <code>la_flow_events</code> database table.</p><blockquote><p><strong>Status:</strong> Server-side pipeline is complete (<code>AuditConsumer</code> + <code>la_flow_events</code>). The sandbox-side <code>natsAuditWriter</code> is in development — sandbox currently writes to local file only.</p></blockquote><p>Query audit events via the dashboard or API:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/audit/flow?agentName=agent-001&amp;from=2026-05-18T00:00:00Z</span></span></code></pre></div><h2 id="gvisor-runsc-mode" tabindex="-1">gVisor runsc Mode <a class="header-anchor" href="#gvisor-runsc-mode" aria-label="Permalink to &quot;gVisor runsc Mode&quot;">​</a></h2><p><code>--mode gvisor</code> provides syscall-level isolation by running the AI agent inside a gVisor runsc container. This mode uses a <strong>two-phase architecture</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Phase 1 (pod kernel):                   Phase 2 (runsc --network=host):</span></span>
<span class="line"><span>  bootstrapAgent()                       PID 1: AI agent binary</span></span>
<span class="line"><span>  ① NATS registration                   gVisor sentry intercepts all</span></span>
<span class="line"><span>  ② wireguard-go → wg0 (real TUN)       syscalls, but networking is</span></span>
<span class="line"><span>  ③ Routes + iptables on pod            handled by the pod kernel wg0</span></span></code></pre></div><p>The AI agent traffic flows: <code>gVisor sentry → host kernel passthrough → pod routing → wg0 → WireGuard → overlay</code>. gVisor provides security isolation (syscall interception), while all networking runs on the real kernel.</p><h3 id="gvisor-mode-flags" tabindex="-1">gVisor Mode Flags <a class="header-anchor" href="#gvisor-mode-flags" aria-label="Permalink to &quot;gVisor Mode Flags&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lattice</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sandbox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gvisor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agent-001</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --server-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://latticed:8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --token</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lt-xxx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --agent-rootfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/lattice/agent-rootfs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --agent-binary</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/bin/ai-agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --agent-args</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --model,gpt-4</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Flag</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>--mode gvisor</code></td><td>Yes</td><td>Enable gVisor runsc isolation</td></tr><tr><td><code>--agent-rootfs</code></td><td>Yes</td><td>Path to container root filesystem</td></tr><tr><td><code>--agent-binary</code></td><td>Yes</td><td>AI agent binary inside the container</td></tr><tr><td><code>--agent-args</code></td><td>No</td><td>Arguments passed to the AI agent binary</td></tr><tr><td><code>--egress-allow</code></td><td>No</td><td>CIDR ranges to allow outbound (enforced by pod iptables/eBPF)</td></tr><tr><td><code>--egress-default-deny</code></td><td>No</td><td>Whitelist egress mode</td></tr></tbody></table><h3 id="security-boundary" tabindex="-1">Security Boundary <a class="header-anchor" href="#security-boundary" aria-label="Permalink to &quot;Security Boundary&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Layer</th><th>Mechanism</th></tr></thead><tbody><tr><td>Syscall isolation</td><td>gVisor sentry intercepts all AI agent syscalls</td></tr><tr><td>Network access</td><td>Pod iptables/eBPF on wg0</td></tr><tr><td>WireGuard keys</td><td>On pod kernel, never inside gVisor</td></tr><tr><td>CAP_NET_ADMIN</td><td>Not granted to gVisor container</td></tr><tr><td>TUN device</td><td>Not available inside gVisor</td></tr></tbody></table>`,37)])])}const c=a(n,[["render",l]]);export{g as __pageData,c as default};
